import{_ as a,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Lost reasons","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/lost-reasons.md","filePath":"master/sales/crm/configuration/lost-reasons.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/configuration/lost-reasons.md"};function d(h,e,c,g,u,p){const o=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="lost-reasons" tabindex="-1">Lost reasons <a class="header-anchor" href="#lost-reasons" aria-label="Permalink to &quot;Lost reasons&quot;">​</a></h1><p>A lost reason is a short answer to the question &quot;why did we lose this deal?&quot;. Your team picks one when they mark a lead or opportunity as lost. Over time the reasons show you what to fix, such as price or stock.</p><blockquote><p><strong>In simple words:</strong> A lost reason is a ready-made explanation you choose when a deal is lost.</p></blockquote><p>Open <code>CRM → Configuration → Pipeline → Lost Reasons</code>.</p><h2 id="the-lost-reason-list" tabindex="-1">The lost reason list <a class="header-anchor" href="#the-lost-reason-list" aria-label="Permalink to &quot;The lost reason list&quot;">​</a></h2>',5)),s(o,{src:"/images1/crm/lost-reasons-list.png",alt:"Lost reasons list with the Active and Archived tabs and three reasons"}),e[1]||(e[1]=t('<p>The default reasons are <strong>No resources or skills available</strong>, <strong>Not enough stock</strong> and <strong>Too expensive</strong>.</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>Active:</em></strong> Reasons you can pick. The badge shows how many there are.</li><li><strong><em>Archived:</em></strong> Reasons you deleted. The badge shows how many there are.</li></ul><p><strong>Example:</strong> The dev data has 3 active reasons and 0 archived.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Description:</em></strong> The text of the reason. You can sort by it.</li><li><strong><em>Created By:</em></strong> The user who added it.</li><li><strong><em>Created At</em></strong> and <strong><em>Updated At:</em></strong> Hidden at first. Show them with the column toggle.</li></ul><h3 id="search-sort-and-export" tabindex="-1">Search, sort and export <a class="header-anchor" href="#search-sort-and-export" aria-label="Permalink to &quot;Search, sort and export&quot;">​</a></h3><ul><li>Type in the search box to find a reason.</li><li>Click a heading to sort. The list starts sorted by description.</li><li>Select rows and use the bulk actions to export, delete, restore or delete for good.</li></ul><h2 id="create-a-lost-reason" tabindex="-1">Create a lost reason <a class="header-anchor" href="#create-a-lost-reason" aria-label="Permalink to &quot;Create a lost reason&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Pipeline → Lost Reasons</code>.</li><li>Click <strong>New Lost Reason</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',10)),s(o,{src:"/images1/crm/lost-reasons-form.png",alt:"Create Lost Reason dialog filled with Chose a competitor"}),e[2]||(e[2]=t('<ul><li><strong><em>Description:</em></strong> The reason text. Required. Up to 255 characters.</li></ul><p><strong>Example:</strong> Enter <code>Chose a competitor</code>. A notice says the lost reason was created.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Edit</strong></td><td>Active tab</td><td>Changes the text. A notice says <strong>Lost reason updated</strong>.</td></tr><tr><td><strong>Delete</strong></td><td>Active tab</td><td>Moves the reason to <strong>Archived</strong>.</td></tr><tr><td><strong>Restore</strong></td><td>Archived tab</td><td>Brings the reason back to <strong>Active</strong>.</td></tr><tr><td><strong>Delete</strong> (permanent)</td><td>Archived tab</td><td>Removes the reason for good. A notice says it has been permanently deleted.</td></tr></tbody></table><p>An archived reason cannot be picked on a new lost deal.</p><h2 id="use-a-lost-reason" tabindex="-1">Use a lost reason <a class="header-anchor" href="#use-a-lost-reason" aria-label="Permalink to &quot;Use a lost reason&quot;">​</a></h2><ol><li>Open a lead or an opportunity.</li><li>Click <strong>Lost</strong>.</li><li>In the <strong>Mark as lost</strong> dialog, choose a <strong>Lost Reason</strong> and write a <strong>Closing Note</strong>.</li><li>Click <strong>Mark as Lost</strong>.</li></ol><p>See <a href="./../pipeline/mark-won-lost.html">Mark won or lost</a>. You can also mark several records as lost at once from a list or a report.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The reason is saved on the lost record. Reports can group by <strong>Lost Reason</strong>.</li><li>Archiving a reason does not change records that already use it.</li><li>Check the reasons in <a href="./../reporting/lead-analysis.html">Lead analysis</a>: open the <strong>Lost</strong> tab and group by <strong>Lost Reason</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep reasons specific. &quot;Too expensive&quot; helps you decide on a discount. &quot;Other&quot; does not.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../pipeline/mark-won-lost.html">Mark won or lost</a></li><li><a href="./../reporting/lead-analysis.html">Lead analysis</a></li><li><a href="./">CRM configuration</a></li></ul>',13))])}const _=a(l,[["render",d]]);export{b as __pageData,_ as default};
